/* Copyright 2026 Rhett Creighton; SPDX-License-Identifier: Apache-2.0.
 * purpose: The fixed-result compiler child's seccomp filter: a classic-BPF
 *          allowlist for x86-64 generated byte for byte, so its SHA3-256 is
 *          the seccomp_filter_sha3 pin and root installs the exact bytes at
 *          /etc/z23verify/fixed_result.seccomp.bpf (the layout bwrap
 *          --seccomp reads). Also a reference evaluator and a loader, so a
 *          test can check the policy both in software and in the kernel. */
#ifndef ZCL_VERIFY_FIXED_RESULT_SECCOMP_H
#define ZCL_VERIFY_FIXED_RESULT_SECCOMP_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define ZCL_FRS_MAX_INSNS 255u
#define ZCL_FRS_INSN_BYTES 8u
#define ZCL_FRS_MAX_BYTES (ZCL_FRS_MAX_INSNS * ZCL_FRS_INSN_BYTES)

/* Actions (linux/seccomp.h), as the evaluator reports them. */
#define ZCL_FRS_KILL_PROCESS 0x80000000u
#define ZCL_FRS_ALLOW 0x7fff0000u
#define ZCL_FRS_ERRNO 0x00050000u

/* The seccomp_data a filter sees. */
struct zcl_frs_data {
    int32_t nr;
    uint32_t arch;
    uint64_t ip;
    uint64_t args[6];
};

/* Writes the filter (little-endian sock_filter records) and its length.
 * Refuses on a host that is not x86-64: the numbers are x86-64 numbers. */
bool zcl_frs_build(uint8_t out[ZCL_FRS_MAX_BYTES], size_t *len,
                   const char **why);
/* SHA3-256 of exactly those bytes. */
bool zcl_frs_sha3(uint8_t digest[32], size_t *insns, const char **why);
/* Runs the classic-BPF program the way the kernel does for seccomp; an
 * invalid program returns ZCL_FRS_KILL_PROCESS. */
uint32_t zcl_frs_eval(const uint8_t *prog, size_t len,
                      const struct zcl_frs_data *d);
/* Sets no_new_privs and installs the filter on the calling thread. */
bool zcl_frs_install(const uint8_t *prog, size_t len, const char **why);

/* The allowlist, for review. */
size_t zcl_frs_allowed_count(void);
bool zcl_frs_allowed(size_t i, int *nr, const char **name, const char **rule);

#endif
